//! Compares the automatic seeds (`dca_algo::autoseed`) with the Python plugin.
//!
//! `fixtures/autoseed.json` is generated by `fixtures/gen_autoseed.py` from
//! the plugin's own `autoseed.py` (python3 + numpy, no Blender; the
//! Blender-only `gpu_query` is replaced by an exact brute-force nearest
//! point). The demo arches are rebuilt here from the draws recorded in the
//! fixture, so the plugin and the port see the same mesh.

use std::collections::BTreeMap;
use std::path::PathBuf;

use dc_case::Fdi;
use dca_algo::anatomy::Arch;
use dca_algo::autoseed::{self, DpProblem, Options};
use dca_algo::demo::{self, Draws, Severity};
use glam::{DMat3, DMat4, DVec3};
use serde_json::Value;

fn fixture() -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/autoseed.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn num(v: &Value) -> f64 {
    v.as_f64().unwrap_or(f64::NAN)
}

fn nums(v: &Value) -> Vec<f64> {
    v.as_array().unwrap().iter().map(num).collect()
}

fn vec3(v: &Value) -> DVec3 {
    let n = nums(v);
    DVec3::new(n[0], n[1], n[2])
}

fn fdi(n: u64) -> Fdi {
    Fdi::new(n as u8).unwrap()
}

fn arch_of(v: &Value) -> Arch {
    if v == "UPPER" {
        Arch::Upper
    } else {
        Arch::Lower
    }
}

fn close(a: f64, b: f64, tol: f64, what: &str) {
    assert!(
        (a - b).abs() <= tol * (1.0 + b.abs()),
        "{what}: {a} vs {b} (tol {tol})"
    );
}

/// Largest difference between two profiles (`None` in the fixture = NaN).
fn max_diff(a: &[f64], b: &[f64], what: &str) -> f64 {
    assert_eq!(a.len(), b.len(), "{what}: length");
    a.iter()
        .zip(b)
        .map(|(x, y)| {
            if x.is_nan() || y.is_nan() {
                assert_eq!(x.is_nan(), y.is_nan(), "{what}: NaN pattern");
                0.0
            } else {
                (x - y).abs()
            }
        })
        .fold(0.0, f64::max)
}

#[test]
fn dynamic_programming_matches_the_plugin() {
    let fx = fixture();
    for (i, c) in fx["dp"].as_array().unwrap().iter().enumerate() {
        let skippable: Vec<bool> = c["skippable"]
            .as_array()
            .unwrap()
            .iter()
            .map(|b| b.as_bool().unwrap())
            .collect();
        let mid = c["mid"][0]
            .as_u64()
            .map(|t| (t as usize, num(&c["mid"][1]), num(&c["mid"][2])));
        let (w, bl, dip, cum, sig, crown) = (
            nums(&c["w"]),
            nums(&c["bl"]),
            nums(&c["dip"]),
            nums(&c["bl_cum"]),
            nums(&c["sigma"]),
            nums(&c["crown"]),
        );
        assert_eq!(dip.len() as u64, c["nb"].as_u64().unwrap());
        let (cost, segs) = autoseed::dp(&DpProblem {
            w_bins: &w,
            bl_exp: &bl,
            dip: &dip,
            bl_cum: &cum,
            sigma: &sig,
            mid,
            crown: &crown,
            skippable: &skippable,
            bin_mm: 0.25,
            free_ends: None,
        });
        close(cost, num(&c["cost"]), 1e-12, &format!("dp {i} cost"));
        let want: Vec<Option<(usize, usize)>> = c["segs"]
            .as_array()
            .unwrap()
            .iter()
            .map(|s| {
                s.as_array().map(|p| {
                    (
                        p[0].as_u64().unwrap() as usize,
                        p[1].as_u64().unwrap() as usize,
                    )
                })
            })
            .collect();
        assert_eq!(segs, want, "dp {i} segments");
    }
}

#[test]
fn helpers_match_the_plugin() {
    let fx = fixture();
    for item in fx["names"].as_array().unwrap() {
        let name = item[0].as_str();
        let got = name.and_then(autoseed::arch_from_name);
        let want = item[1].as_str().map(|a| arch_of(&Value::from(a)));
        assert_eq!(got, want, "{name:?}");
    }
    let w = &fx["widths"];
    let widths: BTreeMap<Fdi, f64> = w["widths"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(k, v)| (fdi(k.parse().unwrap()), num(v)))
        .collect();
    let (cost, k) = autoseed::width_fit(&widths);
    close(cost, num(&w["fit"][0]), 1e-12, "width_fit cost");
    close(k, num(&w["fit"][1]), 1e-12, "width_fit scale");
    let out = autoseed::width_outliers(&widths, 0.3, 3);
    let want = w["outliers"].as_array().unwrap();
    assert_eq!(out.len(), want.len());
    for ((f, m, e), o) in out.iter().zip(want) {
        assert_eq!(f.get() as u64, o[0].as_u64().unwrap());
        close(*m, num(&o[1]), 1e-12, "outlier width");
        close(*e, num(&o[2]), 1e-12, "outlier expected");
    }
    close(
        autoseed::incisor_molar_ratio(&widths).unwrap(),
        num(&w["ratio"]),
        1e-12,
        "ratio",
    );
    assert!(w["ratio_none"].is_null());
    assert_eq!(
        autoseed::incisor_molar_ratio(&[(fdi(11), 8.0)].into_iter().collect()),
        None
    );

    let s = &fx["sequences"];
    let ids = |v: &[Fdi]| v.iter().map(|f| u64::from(f.get())).collect::<Vec<_>>();
    let list = |v: &Value| -> Vec<u64> {
        v.as_array()
            .unwrap()
            .iter()
            .map(|x| x.as_u64().unwrap())
            .collect()
    };
    assert_eq!(
        ids(&autoseed::expected_sequence(Arch::Upper, false, &[])),
        list(&s["upper"])
    );
    assert_eq!(
        ids(&autoseed::expected_sequence(Arch::Lower, true, &[fdi(36)])),
        list(&s["lower_third_missing36"])
    );
    let cands = autoseed::candidate_sequences(Arch::Lower, false, &[fdi(45)], None);
    let want = s["candidates_lower_missing45"].as_array().unwrap();
    assert_eq!(cands.len(), want.len());
    for (c, w) in cands.iter().zip(want) {
        assert_eq!(ids(&c.teeth), list(&w[0]));
        assert_eq!(c.prior, num(&w[1]));
        assert_eq!(
            c.ends.map(u64::from).to_vec(),
            list(&w[2]),
            "candidate ends"
        );
    }
}

/// Replays the draws recorded by the fixture.
struct Replay {
    u: Vec<f64>,
    z: Vec<f64>,
    iu: usize,
    iz: usize,
}

impl Draws for Replay {
    fn uniform(&mut self, lo: f64, hi: f64) -> f64 {
        self.iu += 1;
        lo + (hi - lo) * self.u[self.iu - 1]
    }

    fn normal(&mut self, mean: f64, sd: f64) -> f64 {
        self.iz += 1;
        mean + sd * self.z[self.iz - 1]
    }
}

#[test]
fn seeds_on_the_demo_arches_match_the_plugin() {
    let fx = fixture();
    for run in fx["runs"].as_array().unwrap() {
        let arch = arch_of(&run["arch"]);
        let severity = match run["severity"].as_str().unwrap() {
            "MILD" => Severity::Mild,
            "MODERATE" => Severity::Moderate,
            _ => Severity::Severe,
        };
        let third = run["third_molars"].as_bool().unwrap();
        let name = format!("{arch:?} {severity:?} third={third}");
        let mut replay = Replay {
            u: nums(&fx["U"]),
            z: nums(&fx["Z"]),
            iu: 0,
            iz: 0,
        };
        let model = demo::generate_with(arch, severity, third, &mut replay);
        let mut v: Vec<DVec3> = model.mesh.positions.iter().map(|p| p.as_dvec3()).collect();
        if run["posed"].as_bool().unwrap() {
            let r = run["R"].as_array().unwrap();
            let rows: Vec<DVec3> = r.iter().map(vec3).collect();
            let m = DMat3::from_cols(rows[0], rows[1], rows[2]).transpose();
            let t = vec3(&run["t"]);
            for p in &mut v {
                *p = m * *p + t;
            }
        }
        let t = &model.mesh.tris;
        assert_eq!(
            v.len() as u64,
            run["n_vertices"].as_u64().unwrap(),
            "{name}"
        );
        let sum: DVec3 = v.iter().copied().sum();
        assert!(
            (sum - vec3(&run["vertex_sum"])).length() < 1e-3 * v.len() as f64 * 1e-3,
            "{name}: vertex sum {sum:?}"
        );

        // occlusal axis and arch frame
        let (n, c) = autoseed::occlusal_axis(&v, t).unwrap();
        assert!(
            (n - vec3(&run["occlusal"]["n"])).length() < 1e-9,
            "{name}: n {n:?}"
        );
        assert!(
            (c - vec3(&run["occlusal"]["c"])).length() < 1e-9,
            "{name}: c"
        );
        let data = autoseed::arch_data(&v, t).unwrap();
        let want_m = run["frame"].as_array().unwrap();
        let m: DMat4 = data.frame;
        let mut dframe: f64 = 0.0;
        for (i, row) in want_m.iter().enumerate() {
            for (j, x) in nums(row).iter().enumerate() {
                dframe = dframe.max((m.col(j)[i] - x).abs());
            }
        }
        assert!(dframe < 1e-6, "{name}: frame differs by {dframe}");

        // arch curve
        let cv = &run["curve"];
        assert_eq!(
            data.curve.points.len() as u64,
            cv["n"].as_u64().unwrap(),
            "{name}: curve"
        );
        close(data.curve.s[0], num(&cv["s0"]), 1e-9, "curve s0");
        close(
            *data.curve.s.last().unwrap(),
            num(&cv["s1"]),
            1e-9,
            "curve s1",
        );
        for (s, p) in nums(&cv["s"]).iter().zip(cv["points"].as_array().unwrap()) {
            let q = data.curve.point(*s);
            let w = nums(p);
            assert!(
                (q.x - w[0]).abs() + (q.y - w[1]).abs() < 1e-8,
                "{name}: curve at {s}"
            );
        }

        // profiles
        let pr = &data.profiles;
        let wp = &run["profiles"];
        assert_eq!(pr.nb as u64, wp["nb"].as_u64().unwrap(), "{name}: bins");
        assert_eq!(
            pr.points.len() as u64,
            wp["n_points"].as_u64().unwrap(),
            "{name}: profiled points"
        );
        close(pr.s_min, num(&wp["s_min"]), 1e-9, "s_min");
        close(pr.s_max, num(&wp["s_max"]), 1e-9, "s_max");
        let mut worst: f64 = 0.0;
        for (key, got) in [
            ("H", &pr.h),
            ("dip", &pr.dip),
            ("BL", &pr.bl),
            ("crown", &pr.crown),
            ("off_top", &pr.off_top),
            ("dHbl", &pr.dh_bl),
        ] {
            let d = max_diff(got, &nums(&wp[key]), &format!("{name} {key}"));
            // the fixture rounds to 1e-6
            assert!(d < 2e-6, "{name}: profile {key} differs by {d}");
            worst = worst.max(d);
        }

        // the proposal
        let opts = Options {
            include_third: third,
            ..Default::default()
        };
        let p = autoseed::propose(&v, t, arch, &opts, Some(&data)).unwrap();
        let want: BTreeMap<u8, DVec3> = run["seeds"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(k, x)| (k.parse().unwrap(), vec3(x)))
            .collect();
        let got: BTreeMap<u8, DVec3> = p.seeds.iter().map(|s| (s.fdi.get(), s.position)).collect();
        assert_eq!(
            got.keys().collect::<Vec<_>>(),
            want.keys().collect::<Vec<_>>(),
            "{name}: teeth"
        );
        let dseed = got
            .iter()
            .map(|(f, q)| (*q - want[f]).length())
            .fold(0.0, f64::max);
        assert!(dseed < 1e-6, "{name}: seeds differ by {dseed} mm");
        let d = &run["diag"];
        let dg = &p.diagnostics;
        assert_eq!(dg.scale, num(&d["scale"]), "{name}: scale");
        close(dg.cost, num(&d["cost"]), 1e-9, "cost");
        close(dg.cost_raw, num(&d["cost_raw"]), 1e-9, "cost_raw");
        close(
            dg.arch_length_mm,
            num(&d["arch_length_mm"]),
            1e-9,
            "arch length",
        );
        assert_eq!(dg.teeth as u64, d["teeth"].as_u64().unwrap());
        assert_eq!(
            [u64::from(dg.molars.right), u64::from(dg.molars.left)],
            [
                d["molars"][0].as_u64().unwrap(),
                d["molars"][1].as_u64().unwrap()
            ]
        );
        assert_eq!(
            dg.absent_inside
                .iter()
                .map(|f| u64::from(*f))
                .collect::<Vec<_>>(),
            d["absent_inside"]
                .as_array()
                .unwrap()
                .iter()
                .map(|x| x.as_u64().unwrap())
                .collect::<Vec<_>>()
        );
        let cands = d["candidates"].as_array().unwrap();
        assert_eq!(dg.candidates.len(), cands.len());
        for (c, w) in dg.candidates.iter().zip(cands) {
            // the plugin rounds the costs of the candidates to 0.01
            assert!(
                (c.cost - num(&w[1])).abs() <= 0.005 + 1e-9,
                "{name}: {c:?} {w}"
            );
            assert!(
                (c.total - num(&w[2])).abs() <= 0.005 + 1e-9,
                "{name}: {c:?} {w}"
            );
        }

        // upper / lower cues
        let cov = autoseed::palate_coverage(&v, t, Some(data.frame)).unwrap();
        close(cov, num(&run["palate_coverage"]), 1e-12, "palate coverage");
        let side = autoseed::posterior_cusp_side(pr, autoseed::BIN_MM, autoseed::WILSON_MM);
        match run["posterior_cusp_side"].as_f64() {
            Some(w) => close(side.unwrap(), w, 1e-9, "cusp side"),
            None => assert!(side.is_none()),
        }
        let det = autoseed::detect_arch(&v, t, None).unwrap();
        assert_eq!(
            det.arch,
            arch_of(&run["detect"]["arch"]),
            "{name}: detected arch"
        );
        close(
            det.confidence,
            num(&run["detect"]["confidence"]),
            1e-9,
            "confidence",
        );
        println!(
            "{name}: frame {dframe:.2e}, profiles {worst:.2e}, seeds {dseed:.2e} mm, {} teeth",
            got.len()
        );
    }
}
